import unittest

from shop import apply_discount


class ApplyDiscountTests(unittest.TestCase):
    def test_applies_percentage_to_price(self):
        self.assertEqual(apply_discount(100, 20), 80)

    def test_zero_percent_leaves_price_unchanged(self):
        self.assertEqual(apply_discount(49.99, 0), 49.99)

    def test_full_discount_reduces_price_to_zero(self):
        self.assertEqual(apply_discount(75, 100), 0)


if __name__ == "__main__":
    unittest.main()

